llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Delpazolid, a close oxazolidinone analogue with a hydroxymethyl group, showed 99.75% absolute oral bioavailability in healthy volunteers, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Linezolid, an approved oxazolidinone, has approximately 100% oral bioavailability, supporting that the oxazolidinone scaffold in the query can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fosravuconazole, a phosphate prodrug, achieved 100% oral bioavailability in humans, supporting that the phosphate ester in the query can be cleaved and absorbed to yield high exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "YH4808, an oxazolidinone analogue, had low absolute bioavailability of 10.1%, providing contradictory evidence that some oxazolidinones can have poor F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Cadazolid, a larger oxazolidinone-containing hybrid, had very low oral bioavailability, but its structural divergence and lower transferability limit its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a phosphate prodrug of a tedizolid-like oxazolidinone. The closest oxazolidinone analogues (delpazolid, linezolid) show near-complete oral bioavailability, and phosphate prodrugs such as fosravuconazole also achieve 100% F, indicating that the charged phosphate is cleaved and does not preclude absorption. Although YH4808 and cadazolid show low F, their structural differences limit transfer. Overall, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query (tedizolid phosphate) were provided.",
    "The extent of phosphate cleavage and absorption of the active moiety is inferred from analogues rather than measured for the query.",
    "The effect of the phosphate group on intestinal permeability and transporter-mediated absorption is not directly characterized in the closest analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

